#[inline(always)]
fn bit(words: &[u64; PRODUCT_LIMBS], index: usize) -> bool {
    ((words[index / 64] >> (index % 64)) & 1) != 0
}

#[inline]
fn multiply_two_over_pi(mantissa: u128) -> [u64; PRODUCT_LIMBS] {
    let parts = [mantissa as u64, (mantissa >> 64) as u64];
    let mut product = [0_u64; PRODUCT_LIMBS];

    let mut part_index = 0;
    while part_index < parts.len() {
        let part = parts[part_index];
        let mut carry = 0_u128;
        let mut i = 0;
        while i < TWO_OVER_PI.len() {
            let output_index = i + part_index;
            let value =
                (TWO_OVER_PI[i] as u128) * (part as u128) + (product[output_index] as u128) + carry;
            product[output_index] = value as u64;
            carry = value >> 64;
            i += 1;
        }

        let mut output_index = TWO_OVER_PI.len() + part_index;
        while carry != 0 {
            let value = (product[output_index] as u128) + carry;
            product[output_index] = value as u64;
            carry = value >> 64;
            output_index += 1;
        }
        part_index += 1;
    }

    product
}

#[inline]
fn reduce_positive(mantissa: u128, exponent: i32, precision: usize) -> (f128, u8) {
    let product = multiply_two_over_pi(mantissa);
    let binary_point = (TWO_OVER_PI_BITS as i32 + (precision as i32 - 1) - exponent) as usize;

    let half = bit(&product, binary_point - 1);
    let mut below_half = false;
    let mut i = 0;
    while i + 1 < binary_point {
        below_half |= bit(&product, i);
        i += 1;
    }
    let integer_is_odd = bit(&product, binary_point);
    let round_up = half && (below_half || integer_is_odd);

    let quotient_low =
        (bit(&product, binary_point) as u8) | ((bit(&product, binary_point + 1) as u8) << 1);
    let quadrant = quotient_low.wrapping_add(round_up as u8) & 3;

    let mut magnitude = product;
    let top_limb = binary_point / 64;
    let top_bits = binary_point % 64;
    if top_bits == 0 {
        magnitude[top_limb] = 0;
    } else {
        magnitude[top_limb] &= (1_u64 << top_bits) - 1;
    }
    let mut clear = top_limb + 1;
    while clear < PRODUCT_LIMBS {
        magnitude[clear] = 0;
        clear += 1;
    }

    if round_up {
        let mut carry = 1_u64;
        let mut limb = 0;
        while limb <= top_limb {
            let inverted = !magnitude[limb];
            let (value, overflow) = inverted.overflowing_add(carry);
            magnitude[limb] = value;
            carry = overflow as u64;
            limb += 1;
        }
        if top_bits == 0 {
            magnitude[top_limb] = 0;
        } else {
            magnitude[top_limb] &= (1_u64 << top_bits) - 1;
        }
    }

    let mut bit_length = binary_point;
    while bit_length != 0 && !bit(&magnitude, bit_length - 1) {
        bit_length -= 1;
    }
    if bit_length == 0 {
        return (0.0_f128, quadrant);
    }

    let retained = bit_length.min(128);
    let shift = bit_length - retained;
    let mut significand = 0_u128;
    let mut j = 0;
    while j < retained {
        if bit(&magnitude, shift + j) {
            significand |= 1_u128 << j;
        }
        j += 1;
    }

    let scale = (2.0_f128).powi(shift as i32 - binary_point as i32);
    let fraction = (significand as f128) * scale;
    let remainder = fraction * core::f128::consts::FRAC_PI_2;
    (if round_up { -remainder } else { remainder }, quadrant)
}

#[inline]
fn apply_sign(remainder: f128, quadrant: u8, negative: bool) -> (f128, u8) {
    if negative {
        (-remainder, 0_u8.wrapping_sub(quadrant) & 3)
    } else {
        (remainder, quadrant)
    }
}

#[inline]
fn rem_pio2_cody_waite_f32(x: f32) -> (f32, u8) {
    let mut k = (x * INV_PIO2_F32).round_ties_even() as i32;
    let mut kf = k as f32;
    let mut r = ((x - kf * PIO2_C1_F32) - kf * PIO2_C2_F32) - kf * PIO2_C3_F32;
    if r > core::f32::consts::FRAC_PI_4 {
        k += 1;
        kf += 1.0_f32;
        r = ((x - kf * PIO2_C1_F32) - kf * PIO2_C2_F32) - kf * PIO2_C3_F32;
    } else if r < -core::f32::consts::FRAC_PI_4 {
        k -= 1;
        kf -= 1.0_f32;
        r = ((x - kf * PIO2_C1_F32) - kf * PIO2_C2_F32) - kf * PIO2_C3_F32;
    }
    (r, (k & 3) as u8)
}

